def compute(vars):
    total_revenue = vars["v1"]
    total_other_income = vars["v2"]
    result = total_revenue + total_other_income

    return {
        "value": result,
        "trace": {
            "total_revenue": total_revenue,
            "total_other_income": total_other_income,
            "output_meta": {
                "currency": "USD",
                "scale": "thousand",
                "unit": None
            }
        }
    }
